/** Actual source-only first-run. Existing DB is supplied only through the visible escape chooser. */
public final class FirstRunSetupAcceptance {
 static Path out;static Robot robot;static final java.util.List<String> report=new ArrayList<>();
 static JComponent panel(){return Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(window->JournalSnapshots.all(window).stream()).filter(c->c instanceof JComponent&&c.isShowing()&&c.getClass().getName().endsWith(".LibrarySetupPanel")).map(c->(JComponent)c).findFirst().orElse(null);}
 static <T extends Component>T named(String name,Class<T> type)throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(panel()).stream().filter(type::isInstance).map(type::cast).filter(c->name.equals(c.getName())).findFirst().orElseThrow());}
 static AbstractButton textButton(String prefix)throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(panel()).stream().filter(c->c instanceof AbstractButton b&&b.isShowing()&&b.getText()!=null&&b.getText().startsWith(prefix)).map(c->(AbstractButton)c).findFirst().orElseThrow());}
 static String text()throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.texts(panel()));}
 static void check(boolean value,String label){if(!value)throw new AssertionError(label);report.add("PASS: "+label);}
 static void click(Component component)throws Exception{JournalSnapshots.click(component);}
 static void tab(int index)throws Exception{JTabbedPane tabs=named("setup-navigation",JTabbedPane.class);Point p=JournalSnapshots.edt(()->{Rectangle r=tabs.getBoundsAt(index);Point point=tabs.getLocationOnScreen();point.translate(r.x+r.width/2,r.y+r.height/2);return point;});robot.mouseMove(p.x,p.y);robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);robot.delay(200);check(JournalSnapshots.edt(tabs::getSelectedIndex)==index,"Native setup navigation selects tab "+index);}
 static int step()throws Exception{return JournalSnapshots.edt(()->{Component progress=namedUnchecked("setup-progress",Component.class);String value=progress instanceof JLabel label?label.getText():((javax.swing.text.JTextComponent)progress).getText();var matcher=java.util.regex.Pattern.compile("Step (\\d+) of 5").matcher(value);if(!matcher.find())throw new AssertionError(value);return Integer.parseInt(matcher.group(1))-1;});}
 static void wizard(int wanted)throws Exception{tab(0);for(int pass=0;pass<8&&step()!=wanted;pass++)click(named(step()<wanted?"setup-next":"setup-back",AbstractButton.class));check(step()==wanted,"Actual wizard reaches step "+wanted);}
 static void checked(String name,boolean value)throws Exception{AbstractButton box=named(name,AbstractButton.class);if(JournalSnapshots.edt(box::isSelected)!=value)click(box);}
 static void chooseGame(String prefix)throws Exception{JComboBox<?> game=named("setup-active-game",JComboBox.class);JournalSnapshots.edt(()->{for(int i=0;i<game.getItemCount();i++)if(game.getItemAt(i).toString().startsWith(prefix)){game.setSelectedIndex(i);return null;}throw new AssertionError("Game missing: "+prefix);});robot.delay(150);}
 static void snap(String name)throws Exception{Window window=JournalSnapshots.edt(()->SwingUtilities.getWindowAncestor(panel()));robot.mouseMove(5,5);robot.delay(200);ImageIO.write(robot.createScreenCapture(JournalSnapshots.edt(window::getBounds)),"png",out.resolve(name+".png").toFile());}
 static void selectDatabase(Path path)throws Exception{selectFile("setup-open-database",path);}
 static void selectFile(String control,Path path)throws Exception{
  click(named(control,AbstractButton.class));ResearchAcceptance.until(()->JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(window->JournalSnapshots.all(window).stream()).anyMatch(JFileChooser.class::isInstance)),"native existing database chooser");
  JFileChooser chooser=JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(window->JournalSnapshots.all(window).stream()).filter(JFileChooser.class::isInstance).map(JFileChooser.class::cast).findFirst().orElseThrow());JournalSnapshots.edt(()->{chooser.setSelectedFile(path.toFile());return null;});JButton approve=JournalSnapshots.edt(()->JournalSnapshots.all(chooser).stream().filter(c->c instanceof JButton b&&b.isShowing()&&Objects.equals(b.getText(),UIManager.getString("FileChooser.openButtonText"))).map(c->(JButton)c).findFirst().orElseThrow());click(approve);
 }
 public static void main(String[] args)throws Exception{
  if(args.length!=4)throw new IllegalArgumentException("SOURCE_JAR EXISTING_VALID_DB EMPTY_OUTPUT DARK_OR_LIGHT_OR_SETTINGS");out=Path.of(args[2]);Files.createDirectories(out);try(var entries=Files.list(out)){if(entries.findAny().isPresent())throw new IllegalArgumentException("Output must be empty");}report.add("Source JAR SHA-256: "+JournalSnapshots.hash(Path.of(args[0])));report.add(args[3].equals("SETTINGS")?"Actual Main management round-trip with a saved existing-DB preference; no database override or bundled database.":"Actual Main first-run; no database override, no bundled database, no saved database path; explicit metadata checks only, no extraction/import claim.");int exit=0;
  if(args[3].equals("SETTINGS")){settingsOnly(args);return;}
  try{
   check(System.getProperty("wowforever.database")==null,"No external database override supplied");check(dev.wowforever.app.Main.class.getResource("/data/wowforever.sqlite")==null,"Exact source-only artifact has no bundled database");Preferences database=Preferences.userRoot().node("/dev/wowforever/app/db");check(database.get("database-path","").isBlank(),"Fresh preferences have no installed database fallback");Path appdata=Path.of(System.getenv("XDG_DATA_HOME"));try(var entries=Files.walk(appdata)){check(entries.noneMatch(Files::isRegularFile),"Fresh XDG data starts empty");}
   ThemeManager.apply(ThemeManager.Mode.valueOf(args[3]));dev.wowforever.app.Main.main(new String[0]);ResearchAcceptance.until(()->JournalSnapshots.edt(FirstRunSetupAcceptance::panel)!=null,"actual first-run setup workspace");robot=new Robot();robot.setAutoDelay(55);JournalSnapshots.robot=robot;
   for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{Window window=SwingUtilities.getWindowAncestor(panel());window.setBounds(20,20,width,900);return null;});robot.delay(200);for(int stage=0;stage<5;stage++){wizard(stage);snap("setup-"+args[3].toLowerCase(Locale.ROOT)+"-step-"+stage+"-"+width);}for(int page:new int[]{1}){tab(page);snap("setup-"+args[3].toLowerCase(Locale.ROOT)+"-nav-"+page+"-"+width);}}
   wizard(0);check(text().contains("read-only"),"Setup describes WoW installation sources as read-only");wizard(4);check(text().contains(appdata.toString()),"Review shows owned application-data destination");AbstractButton build=named("setup-build-library",AbstractButton.class);check(!JournalSnapshots.edt(build::isEnabled)&&text().contains("not ready"),"Builder remains disabled with explicit not-ready qualification");wizard(3);checked("setup-allow-cdn",true);tab(1);
   checked("setup-source-native",false);check(!JournalSnapshots.edt(()->namedUnchecked("setup-source-wago",AbstractButton.class).isEnabled()),"Wago is unavailable without explicit native source selection");checked("setup-source-native",true);checked("setup-source-wago",true);check(JournalSnapshots.edt(()->namedUnchecked("setup-source-native",AbstractButton.class).isSelected()),"Wago selection retains its explicit Blizzard-native dependency");checked("setup-source-native",false);check(!JournalSnapshots.edt(()->namedUnchecked("setup-source-wago",AbstractButton.class).isSelected()),"Removing native dependency also removes Wago");checked("setup-source-native",true);checked("setup-source-wago",true);click(named("setup-save",AbstractButton.class));
   Preferences draft=Preferences.userRoot().node("/dev/wowforever/app/ui/setup/source-draft");check(draft.getBoolean("forever.source.wago",false)&&draft.getBoolean("forever.source.native",false)&&draft.getBoolean("forever.cdn",false),"Explicit Save persists source choices and CDN consent");
   wizard(1);checked("setup-game-classic",true);tab(1);chooseGame("WoW Classic");checked("setup-source-atlas",true);click(named("setup-save",AbstractButton.class));check(draft.getBoolean("game.classic",false)&&draft.getBoolean("classic.source.atlas",false)&&!draft.getBoolean("classic.source.wago",true),"Selected game and its separate source draft persist");chooseGame("WoW Forever");check(JournalSnapshots.edt(()->namedUnchecked("setup-source-wago",AbstractButton.class).isSelected()),"Switching game restores independent Forever sources");wizard(3);check(JournalSnapshots.edt(()->namedUnchecked("setup-allow-cdn",AbstractButton.class).isSelected()),"CDN permission remains scoped to the selected game");
   Path readOnly=out.resolve("read-only-install-fixture");Files.createDirectory(readOnly);Path marker=readOnly.resolve("acceptance-marker.txt");Files.writeString(marker,"Metadata-only acceptance fixture; this is not a WoW installation.");String markerHash=JournalSnapshots.hash(marker);Files.setPosixFilePermissions(marker,java.nio.file.attribute.PosixFilePermissions.fromString("r--r--r--"));Files.setPosixFilePermissions(readOnly,java.nio.file.attribute.PosixFilePermissions.fromString("r-xr-xr-x"));selectFile("setup-browse-local",readOnly);ResearchAcceptance.until(()->!JournalSnapshots.edt(()->namedUnchecked("setup-cancel-check",AbstractButton.class).isEnabled()),"read-only fixture metadata inspection completes");try(var folderEntries=Files.list(readOnly)){check(JournalSnapshots.hash(marker).equals(markerHash)&&folderEntries.count()==1,"Real local inspector leaves read-only selected-folder fixture unchanged");}report.add("Selected folder is an explicitly synthetic non-installation fixture; no claim of a detected working WoW client.");tab(1);click(named("setup-save",AbstractButton.class));check(draft.get("forever.folder","").equals(readOnly.toAbsolutePath().toString()),"Explicit source draft save remembers selected read-only folder");wizard(3);
   click(named("setup-detect-local",AbstractButton.class));ResearchAcceptance.until(()->!JournalSnapshots.edt(()->namedUnchecked("setup-cancel-check",AbstractButton.class).isEnabled()),"actual local metadata inspection completes");report.add("ACTUAL LOCAL CHECK: "+text());
   click(named("setup-discover-builds",AbstractButton.class));robot.delay(500);AbstractButton cancel=named("setup-cancel-check",AbstractButton.class);if(JournalSnapshots.edt(()->cancel.isEnabled()&&cancel.isShowing())){try{click(cancel);}catch(AssertionError completedDuringClick){if(JournalSnapshots.edt(cancel::isEnabled))throw completedDuringClick;report.add("Compatibility check completed between cancel visibility probe and native click.");}tab(1);wizard(3);check(!JournalSnapshots.edt(cancel::isEnabled),"Actual discovery cancellation or completion leaves check inactive after navigation");report.add("ACTUAL IMPORT BUILD COMPATIBILITY: cancellation requested or completed during click; no extraction or ready-library claim.");}else report.add("ACTUAL IMPORT BUILD COMPATIBILITY completed before cancellation; result text: "+text());
   tab(1);chooseGame("WoW Classic");click(named("setup-save",AbstractButton.class));
   try(var files=Files.walk(appdata)){check(files.noneMatch(file->file.getFileName().toString().endsWith(".sqlite")),"Draft saves and compatibility checks do not create a database");}
   Path invalid=out.resolve("invalid.sqlite");Files.writeString(invalid,"Deliberately invalid acceptance fixture; not a SQLite database.");JComponent previous=JournalSnapshots.edt(FirstRunSetupAcceptance::panel);selectDatabase(invalid);ResearchAcceptance.until(()->JournalSnapshots.edt(()->panel()!=null&&panel()!=previous),"invalid database rejected into setup workspace");check(text().toLowerCase(Locale.ROOT).contains("could not open"),"Invalid existing database stays in setup with visible explanation");tab(1);check(JournalSnapshots.edt(()->namedUnchecked("setup-active-game",JComboBox.class).getSelectedItem().toString().startsWith("WoW Classic"))&&JournalSnapshots.edt(()->namedUnchecked("setup-source-atlas",AbstractButton.class).isSelected()),"New setup instance restores saved active game and per-game source preferences");snap("setup-invalid-database");
   String before=JournalSnapshots.hash(Path.of(args[1]));selectDatabase(Path.of(args[1]));ResearchAcceptance.until(()->JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(window->JournalSnapshots.all(window).stream()).anyMatch(c->c instanceof JournalHomePage)),"validated existing database opens actual Journal Home");check(JournalSnapshots.hash(Path.of(args[1])).equals(before),"Existing database escape validates and opens read-only without changing bytes");managementRoundTrip();
  }catch(Throwable failure){report.add("FAIL: "+failure);failure.printStackTrace();exit=1;}finally{Files.write(out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(exit);
 }
 static void settingsOnly(String[] args)throws Exception{
  int exit=0;try{
   report.add("Additional actual Main startup with explicitly saved existing-DB preference; not a no-database first-run claim.");Preferences.userRoot().node("/dev/wowforever/app/db").put("database-path",Path.of(args[1]).toAbsolutePath().toString());
   String hash=JournalSnapshots.hash(Path.of(args[1]));ThemeManager.apply(ThemeManager.Mode.DARK);dev.wowforever.app.Main.main(new String[0]);
   ResearchAcceptance.until(()->JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).flatMap(w->JournalSnapshots.all(w).stream()).anyMatch(c->c instanceof JournalHomePage)),"actual Main using saved validated database");robot=new Robot();robot.setAutoDelay(55);JournalSnapshots.robot=robot;managementRoundTrip();check(hash.equals(JournalSnapshots.hash(Path.of(args[1]))),"Settings management leaves existing database bytes unchanged");
  }catch(Throwable failure){report.add("FAIL: "+failure);failure.printStackTrace();exit=1;}finally{Files.write(out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(exit);
 }
 static void managementRoundTrip()throws Exception{
  MainFrame frame=JournalSnapshots.edt(()->Arrays.stream(Window.getWindows()).filter(Window::isShowing).filter(MainFrame.class::isInstance).map(MainFrame.class::cast).findFirst().orElseThrow());
  java.lang.reflect.Field field=MainFrame.class.getDeclaredField("controller");field.setAccessible(true);AppController controller=(AppController)field.get(frame);
  JournalSnapshots.edt(()->{controller.open(new dev.wowforever.app.nav.ViewTarget.Entity(new dev.wowforever.app.model.EntityRef(dev.wowforever.app.model.EntityKind.ITEM,251525)));return null;});
  ResearchAcceptance.until(()->JournalSnapshots.edt(()->JournalSnapshots.all(frame).stream().anyMatch(c->c instanceof dev.wowforever.app.ui.detail.HeaderPanel h&&h.isShowing()&&"Item #251525".equals(h.subtitle()))),"actual item before source management");
  Object target=JournalSnapshots.edt(controller::current);Component record=JournalSnapshots.edt(()->JournalSnapshots.all(frame).stream().filter(c->c instanceof dev.wowforever.app.ui.detail.HeaderPanel h&&h.isShowing()&&"Item #251525".equals(h.subtitle())).findFirst().orElseThrow());
  JMenuItem menu=JournalSnapshots.edt(()->Arrays.stream(frame.getJMenuBar().getComponents()).filter(JMenu.class::isInstance).map(JMenu.class::cast).flatMap(menuItem->Arrays.stream(menuItem.getMenuComponents())).filter(c->c instanceof JMenuItem&&"sources-updates-menu".equals(c.getName())).map(JMenuItem.class::cast).findFirst().orElseThrow());
  JMenu settings=JournalSnapshots.edt(()->Arrays.stream(frame.getJMenuBar().getComponents()).filter(c->c instanceof JMenu m&&"Settings".equals(m.getText())).map(JMenu.class::cast).findFirst().orElseThrow());click(settings);click(menu);ResearchAcceptance.until(()->JournalSnapshots.edt(FirstRunSetupAcceptance::panel)!=null,"actual Settings Sources & Updates dialog");
  check(JournalSnapshots.edt(()->namedUnchecked("setup-navigation",JTabbedPane.class).getTabCount())==2,"Setup exposes only library wizard and source-management tabs");
  check(JournalSnapshots.edt(()->namedUnchecked("setup-navigation",JTabbedPane.class).getSelectedIndex())==1,"Settings opens Sources & Updates management directly");
  check(JournalSnapshots.edt(()->JournalSnapshots.all(panel()).stream().noneMatch(c->"setup-open-database".equals(c.getName()))),"Source management omits first-run database escape");
  for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{SwingUtilities.getWindowAncestor(panel()).setSize(width,900);return null;});snap("settings-sources-"+width);}
  Window dialog=JournalSnapshots.edt(()->SwingUtilities.getWindowAncestor(panel()));JournalSnapshots.edt(()->{dialog.dispatchEvent(new WindowEvent(dialog,WindowEvent.WINDOW_CLOSING));return null;});
  ResearchAcceptance.until(()->JournalSnapshots.edt(FirstRunSetupAcceptance::panel)==null,"management dialog closes");
  check(JournalSnapshots.edt(()->controller.current().equals(target)&&record.isShowing()),"Closing source management preserves exact current item and page instance");
 }
 static <T extends Component>T namedUnchecked(String name,Class<T> type){return JournalSnapshots.all(panel()).stream().filter(type::isInstance).map(type::cast).filter(c->name.equals(c.getName())).findFirst().orElseThrow();}
}
